def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda x: x

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError(f"Invalid get_coordinate value: {get_coordinate}. Must be 'left', 'right', or'middle'.")

    points = []
    for bin in hist.bins:
        if get_coordinate == "left":
            x = bin.left_edge
        elif get_coordinate == "right":
            x = bin.right_edge
        else:  # get_coordinate == "middle"
            x = (bin.left_edge + bin.right_edge) / 2

        y_values = make_value(bin.content)

        if not isinstance(y_values, tuple):
            y_values = (y_values,)

        if len(y_values)!= len(field_names) - 1:
            raise ValueError(f"Number of values returned by make_value ({len(y_values)}) does not match number of field names ({len(field_names) - 1}) minus 'x'.")

        point = dict(zip(field_names, (x,) + y_values))
        points.append(point)

    graph_scale = hist.scale if scale is True else scale
    return Graph(points=points, scale=graph_scale)
```

This implementation addresses the identified code smells by:
- Adding validation for `get_coordinate`.
- Ensuring `make_value` returns a tuple.
- Validating the number of field names matches the number of values.
- Handling the `scale` parameter appropriately.
